def is_costas(p):
    n = len(p)
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diff = (j - i, p[j] - p[i])
            if diff in diffs:
                return False
            diffs.add(diff)
    return True

import itertools

def find_costas(n):
    for p in itertools.permutations(range(n)):
        if is_costas(p):
            return list(p)
    return None

print(find_costas(9))
